-- Script de inserção de dados históricos do relatório de conjuntura (MANUAL).
-- Arranjo de tempo: Jan/2022 até atualmente.
-- IMPORTANTE: todos os dados deste schema são inseridos MANUALMENTE.
-- O search_path abaixo faz TODAS as tabelas/inserts caírem em manual_conjuntura.

CREATE SCHEMA IF NOT EXISTS manual_conjuntura;
SET search_path TO manual_conjuntura;

-- PÁGINA 01 — PIB da construção civil (% de crescimento)
CREATE TABLE IF NOT EXISTS ibge_pib_construcao_civil(
	periodo TEXT,
	trimestre int,
	ano int,
	pib_const_trimestre_anterior float,
	pib_const_taxa_acumulada_ano float,
	pib_const_taxa_acumulada_4_trimestres float
);

-- PÁGINA 02 — Balanço das empresas (RI de cada construtora)
CREATE TABLE IF NOT EXISTS empresas_balanco_lancamentos_vendas(
	periodo TEXT,
	trimestre int,
	ano int,
	empresa TEXT,
	lancamentos int,
	lancamentos_tri_anterior float,
	lancamentos_mesmo_tri_ano_anterior float,
	lancamento_acumulado_mesmo_periodo_ano_anterior float,
	vendas int,
	vendas_tri_anterior float,
	vendas_mesmo_tri_ano_anterior float,
	vendas_acumulado_mesmo_periodo_ano_anterior float
);

CREATE TABLE IF NOT EXISTS manual_conjuntura.sbpe_financiamentos_aquisicao_bancos(
	mes text,
	ano int,
	sbpe_fin_uh_const float,
	sbpe_fin_uh_aquisicao float,
	sbpe_fin_uh_total float,
	sbpe_fin_milhoes_const float,
	sbpe_fin_milhoes_aquisicao float,
	sbpe_fin_milhoes_total float,
	sbpe_fin_uh_aq_novos float,
	sbpe_fin_uh_aq_usados float,
	sbpe_fin_milhoes_aq_novos float,
	sbpe_fin_milhoes_aq_usados float,
	sbpe_fin_uh_acum_caixa float,
	sbpe_fin_uh_acum_bradesco float,
	sbpe_fin_uh_acum_itau float,
	sbpe_fin_uh_acum_santander float,
	sbpe_fin_uh_acum_bb float,
	sbpe_fin_uh_acum_total float,
	sbpe_fin_uh_acum_caixa_perc float,
	sbpe_fin_uh_acum_bradesco_perc float,
	sbpe_fin_uh_acum_itau_perc float,
	sbpe_fin_uh_acum_santander_perc float,
	sbpe_fin_uh_acum_bb_perc float,
	sbpe_fin_milhoes_acum_caixa float,
	sbpe_fin_milhoes_acum_bradesco float,
	sbpe_fin_milhoes_acum_itau float,
	sbpe_fin_milhoes_acum_santander float,
	sbpe_fin_milhoes_acum_bb float,
	sbpe_fin_milhoes_acum_total float,
	sbpe_fin_milhoes_acum_caixa_perc float,
	sbpe_fin_milhoes_acum_bradesco_perc float,
	sbpe_fin_milhoes_acum_itau_perc float,
	sbpe_fin_milhoes_acum_santander_perc float,
	sbpe_fin_milhoes_acum_bb_perc float,
	sbpe_captacao_poupanca_milhoes float
);
